    <a class="skip-link" href="#main">Skip to main content</a>

    <main id="main" class="page-shell">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Notification settings</h1>
        <p class="intro">
          Tell us where you want important product updates and account notices to arrive.
        </p>

        <form id="notification-form" novalidate>
          <p class="required-note">
            Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
          </p>

          <fieldset class="form-field" aria-describedby="notification-help notification-error">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-marker" aria-hidden="true">*</span>
            </legend>
            <p id="notification-help" class="field-help">Choose one notification method.</p>
            <p id="notification-error" class="status-message" aria-live="polite"></p>

            <div class="radio-list">
              <label class="radio-option" for="notification-email">
                <input
                  id="notification-email"
                  type="radio"
                  name="notificationPreference"
                  value="email"
                  required
                >
                <span>Email</span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input
                  id="notification-sms"
                  type="radio"
                  name="notificationPreference"
                  value="sms"
                  required
                >
                <span>SMS</span>
              </label>

              <label class="radio-option" for="notification-push">
                <input
                  id="notification-push"
                  type="radio"
                  name="notificationPreference"
                  value="push"
                  required
                >
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>

          <button class="submit-button" type="submit">Save notification preference</button>
        </form>
      </section>
    </main>

    <script>
      const App = {
        init() {
          const form = document.querySelector("#notification-form");
          const radios = Array.from(form.querySelectorAll('input[name="notificationPreference"]'));
          const error = document.querySelector("#notification-error");

          form.addEventListener("submit", (event) => {
            event.preventDefault();

            const selected = radios.find((radio) => radio.checked);
            if (!selected) {
              error.textContent = "Error: Choose how you prefer to receive notifications.";
              radios[0].focus();
              return;
            }

            error.textContent = `Preference saved: ${selected.nextElementSibling.textContent}.`;
          });

          radios.forEach((radio) => {
            radio.addEventListener("change", () => {
              error.textContent = "";
            });
          });
        }
      };

      App.init();
    </script>
